using Warehouse;

namespace Warehouse.Tests;

[TestClass]
public class StockLevelTests
{
    private InventoryTracker _tracker = null!;

    [TestInitialize]
    public void Setup() => _tracker = new InventoryTracker();

    [TestMethod]
    public void GetStockLevel_UnknownSku_ReturnsZero()
    {
        Assert.AreEqual(0, _tracker.GetStockLevel("UNKNOWN-001"));
    }

    [TestMethod]
    public void AddStock_NewSku_SetsLevel()
    {
        _tracker.AddStock("SKU-A", 50);

        Assert.AreEqual(50, _tracker.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void AddStock_ExistingSku_AccumulatesQuantity()
    {
        _tracker.AddStock("SKU-A", 30);
        _tracker.AddStock("SKU-A", 20);

        Assert.AreEqual(50, _tracker.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void RemoveStock_SufficientQuantity_ReducesLevel()
    {
        _tracker.AddStock("SKU-A", 100);
        _tracker.RemoveStock("SKU-A", 40);

        Assert.AreEqual(60, _tracker.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void RemoveStock_ExactQuantity_ReachesZero()
    {
        _tracker.AddStock("SKU-A", 25);
        _tracker.RemoveStock("SKU-A", 25);

        Assert.AreEqual(0, _tracker.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void RemoveStock_InsufficientQuantity_ThrowsInvalidOperation()
    {
        _tracker.AddStock("SKU-A", 10);

        var ex = Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.RemoveStock("SKU-A", 20));

        StringAssert.Contains(ex.Message, "SKU-A");
    }

    [TestMethod]
    public void RemoveStock_NoStock_ThrowsInvalidOperation()
    {
        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.RemoveStock("SKU-A", 1));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void GetStockLevel_InvalidSku_Throws(string? sku)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _tracker.GetStockLevel(sku!));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-5)]
    public void AddStock_InvalidQuantity_Throws(int quantity)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.AddStock("SKU-A", quantity));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    public void RemoveStock_InvalidQuantity_Throws(int quantity)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.RemoveStock("SKU-A", quantity));
    }

    [TestMethod]
    public void MultipleSkus_TrackedIndependently()
    {
        _tracker.AddStock("SKU-A", 10);
        _tracker.AddStock("SKU-B", 25);
        _tracker.RemoveStock("SKU-A", 3);

        Assert.AreEqual(7, _tracker.GetStockLevel("SKU-A"));
        Assert.AreEqual(25, _tracker.GetStockLevel("SKU-B"));
    }
}

[TestClass]
public class ReorderAlertTests
{
    private InventoryTracker _tracker = null!;

    [TestInitialize]
    public void Setup() => _tracker = new InventoryTracker();

    [TestMethod]
    public void NeedsReorder_NoThresholdSet_ReturnsFalse()
    {
        Assert.IsFalse(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    public void NeedsReorder_StockAboveThreshold_ReturnsFalse()
    {
        _tracker.AddStock("SKU-A", 100);
        _tracker.SetReorderThreshold("SKU-A", 20);

        Assert.IsFalse(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    public void NeedsReorder_StockAtThreshold_ReturnsTrue()
    {
        _tracker.AddStock("SKU-A", 20);
        _tracker.SetReorderThreshold("SKU-A", 20);

        Assert.IsTrue(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    public void NeedsReorder_StockBelowThreshold_ReturnsTrue()
    {
        _tracker.AddStock("SKU-A", 5);
        _tracker.SetReorderThreshold("SKU-A", 20);

        Assert.IsTrue(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    public void NeedsReorder_ZeroStockWithThreshold_ReturnsTrue()
    {
        _tracker.SetReorderThreshold("SKU-A", 10);

        Assert.IsTrue(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    public void NeedsReorder_BecomesTrue_AfterRemovingStock()
    {
        _tracker.AddStock("SKU-A", 50);
        _tracker.SetReorderThreshold("SKU-A", 20);
        Assert.IsFalse(_tracker.NeedsReorder("SKU-A"));

        _tracker.RemoveStock("SKU-A", 35);

        Assert.IsTrue(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    public void NeedsReorder_BecomesFalse_AfterAddingStock()
    {
        _tracker.AddStock("SKU-A", 5);
        _tracker.SetReorderThreshold("SKU-A", 20);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-A"));

        _tracker.AddStock("SKU-A", 50);

        Assert.IsFalse(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    public void SetReorderThreshold_ZeroThreshold_IsAllowed()
    {
        _tracker.AddStock("SKU-A", 0);
        _tracker.SetReorderThreshold("SKU-A", 0);

        Assert.IsTrue(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    public void SetReorderThreshold_NegativeThreshold_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.SetReorderThreshold("SKU-A", -1));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    public void NeedsReorder_InvalidSku_Throws(string? sku)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _tracker.NeedsReorder(sku!));
    }
}

[TestClass]
public class WarehouseTransferTests
{
    private InventoryTracker _source = null!;
    private InventoryTracker _destination = null!;

    [TestInitialize]
    public void Setup()
    {
        _source = new InventoryTracker();
        _destination = new InventoryTracker();
    }

    [TestMethod]
    public void TransferTo_ValidTransfer_MovesStock()
    {
        _source.AddStock("SKU-A", 100);

        _source.TransferTo(_destination, "SKU-A", 30);

        Assert.AreEqual(70, _source.GetStockLevel("SKU-A"));
        Assert.AreEqual(30, _destination.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void TransferTo_EntireStock_EmptiesSource()
    {
        _source.AddStock("SKU-A", 50);

        _source.TransferTo(_destination, "SKU-A", 50);

        Assert.AreEqual(0, _source.GetStockLevel("SKU-A"));
        Assert.AreEqual(50, _destination.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void TransferTo_DestinationAlreadyHasStock_Accumulates()
    {
        _source.AddStock("SKU-A", 100);
        _destination.AddStock("SKU-A", 20);

        _source.TransferTo(_destination, "SKU-A", 40);

        Assert.AreEqual(60, _source.GetStockLevel("SKU-A"));
        Assert.AreEqual(60, _destination.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void TransferTo_InsufficientStock_ThrowsAndNoChange()
    {
        _source.AddStock("SKU-A", 10);
        _destination.AddStock("SKU-A", 5);

        Assert.ThrowsException<InvalidOperationException>(
            () => _source.TransferTo(_destination, "SKU-A", 20));

        // Both warehouses unchanged
        Assert.AreEqual(10, _source.GetStockLevel("SKU-A"));
        Assert.AreEqual(5, _destination.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void TransferTo_NullDestination_Throws()
    {
        Assert.ThrowsException<ArgumentNullException>(
            () => _source.TransferTo(null!, "SKU-A", 10));
    }

    [TestMethod]
    public void TransferTo_InvalidQuantity_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _source.TransferTo(_destination, "SKU-A", 0));
    }

    [TestMethod]
    public void TransferTo_TriggersReorderOnSource()
    {
        _source.AddStock("SKU-A", 50);
        _source.SetReorderThreshold("SKU-A", 25);

        _source.TransferTo(_destination, "SKU-A", 30);

        Assert.IsTrue(_source.NeedsReorder("SKU-A"));
    }

